package cn.lvxu.travel;
import android.content.*;import org.json.*;import java.util.*;
final class TagRegistryTest {
 static int run(Context c)throws Exception{SharedPreferences p=c.getSharedPreferences(TagRepository.PREF,0);String original=p.getString(TagRepository.REGISTRY,null);int n=0;try{p.edit().remove(TagRepository.REGISTRY).commit();TagRepository r=new TagRepository(c);check(r.inGroup("sys-preset-1").size()==24,"detailed preset");n++;check(r.inGroup("sys-preset-2").size()==8,"simple preset");n++;TagRepository.Group g=r.createGroup("备份测试组", "描述");TagRepository.Tag label=r.create("备份测试标签",123,Collections.singletonList(g.id));Trip trip=Trip.demo();trip.tagIds.add(label.id);trip.tagNames.put(label.id,label.name);JSONObject backup=r.exportJson();r.delete(label.id,Collections.singletonList(trip));check(trip.tagIds.isEmpty()&&!trip.stops.isEmpty(),"delete removes association only");n++;p.edit().remove(TagRepository.REGISTRY).commit();r=new TagRepository(c);TagRepository.Tag same=r.create("备份测试标签",456);TagRepository.MergePlan plan=r.prepareImport(backup);trip.tagIds.add(label.id);trip.tagNames.put(label.id,label.name);r.remap(trip,plan.ids);r.commitImport(plan);check(trip.tagIds.contains(same.id)&&!trip.tagIds.contains(label.id),"backup remaps equal names");n++;check(r.group(g.id)!=null&&r.find(same.id).groupIds.contains(g.id),"backup preserves group membership");n++;JSONObject before=r.exportJson();JSONObject bad=new JSONObject(backup.toString());bad.getJSONArray("tags").put(bad.getJSONArray("tags").get(0));boolean rejected=false;try{r.prepareImport(bad);}catch(IllegalArgumentException e){rejected=true;}check(rejected&&before.toString().equals(r.exportJson().toString()),"invalid backup makes no changes");n++;Trip stale=Trip.demo();stale.tagIds.add("sys-food");stale.tagNames.put("sys-food","美食");r.delete("sys-food",Collections.emptyList());r.mergeEmbedded(stale);check(r.find("sys-food")==null&&stale.tagIds.isEmpty(),"deleted preset not resurrected by stale editor");n++;return n;}finally{SharedPreferences.Editor edit=p.edit();if(original==null)edit.remove(TagRepository.REGISTRY);else edit.putString(TagRepository.REGISTRY,original);edit.commit();}}
 private static void check(boolean condition,String name){if(!condition)throw new AssertionError(name);}
}
